def fresh(out,allowance=128*1024**2):
 global OWNED
 base.fresh(out,allowance);st=out.stat();OWNED=(out.resolve(),st.st_dev,st.st_ino)

def no_personal_source(path):assert not re.search(r'/home/[A-Za-z0-9_.-]+/|/Users/[A-Za-z0-9_.-]+/',Path(path).read_text()),('Personal host locator in source',Path(path).name)

def canonical_run(run,*,shards=False):
 for name,h in CANONICAL.items():assert sha(run/name)==h,('Canonical T22 identity',name)
 m=read(run/'manifest.json');assert m['status']=='completed' and m['execution_type']=='planned_sequential_segments'
 assert m['forward_attempts']==m['forward_passes']==m['fully_processed_forwards']==776
 assert m['evaluation_forwards']==m['suffix_forwards']==384 and m['anchor_forwards']==8 and m['calibration_forwards']==0
 assert m['source_hashes']==FROZEN_SOURCE_HASHES and m['input_dependencies']==CANONICAL_INPUTS and m['all_final_guards_passed'] is True
 assert m['model_hash_before']==m['model_hash_after'] and m['parameter_versions_unchanged'] is True
 assert m['precision_settings_before']==m['precision_settings_after']
 for name,h in FROZEN_SOURCE_HASHES.items():base.relative_member(name);assert sha(run/'frozen_sources'/name)==h
 for name,h in CANONICAL_INPUTS.items():assert sha(run/name)==h
 inventory=read(run/'numeric_inventory.json');expected={f'inputs/{c}__{w}__{i}__000.npz' for c in CORPORA for w in range(4) for i in ('natural','bos')}
 assert set(inventory)==expected
 if shards:
  assert base.scan_package(run/'inputs',set())=={Path(n).name for n in expected}
  for name,v in inventory.items():assert v=={'sha256':sha(run/name),'bytes':(run/name).stat().st_size}
 return m,inventory

def metadata_objects(run,m):
 dm=read(run/'data_manifest.json');inv=read(run/'exclusion_inventory.json');pre=read(run/'preflight.json');chain=read(run/'known_history_chain.json');review=read(run/'known_history_review.json')
 assert pre['status']=='passed' and pre['history_hash_count']==777 and len(set(chain['history_token_hashes']))==777
 assert sha(run/'known_history_chain.json')==CANONICAL_INPUTS['known_history_chain.json']==review['known_history_chain_sha256']
 assert review['status']=='passed' and review['no_unaccounted_model_experiments'] is True
 template=clean(dm);template.pop('literals');safe(template)
 exclusion={k:clean(inv[k]) for k in ('sources','exclusions','retained_calibration_buffers','history_token_hashes','T21_used_spans','T21_identity_attestations','freshness_scope')}
 assert len(set(exclusion['history_token_hashes']))==777 and len(exclusion['retained_calibration_buffers'])==4 and len(exclusion['T21_used_spans'])==16 and len(exclusion['T21_identity_attestations'])==32
