def safe_arrays(raw,backend):
 import numpy as np
 arrays={};anchor=raw['metadata']['window']==0 and raw['metadata']['identity']=='natural'
 for group in GROUPS:
  expected=set(ARMS)|({'native_repeat','native_identity'} if anchor and not group.startswith('suffix') else set())
  assert set(raw[group])==expected
  for arm,values in raw[group].items():
   if group in ('metrics','suffix'):
    if raw.get('schema')=='l11_key_value_donor_explicit_v1':
     assert set(values)==set(METRICS)|{'pred','final_hidden_sha256'}|({'target_indices','logit_query_indices'} if group=='suffix' else set())
     assert base.hash_value(values['final_hidden_sha256'])
     if group=='suffix':assert values['target_indices'].dtype==values['logit_query_indices'].dtype==np.int64 and np.array_equal(values['target_indices'],np.arange(1,128,dtype=np.int64)) and np.array_equal(values['logit_query_indices'],np.arange(128,dtype=np.int64))
    for name in METRICS:
     value=values[name];n=127 if group=='suffix' and name=='loss' else 128 if group=='suffix' else 511
     assert value.shape==(n,) and value.dtype==(np.bool_ if name.startswith('agreement') else np.float32) and np.isfinite(value).all();arrays[group+'__'+arm+'__'+name]=value
   else:
    if arm=='native_repeat':assert values=={};continue
    if group in ('gate_norms','suffix_gate_norms'):assert set(values)=={10};values=values[10];keys=backend.GATE_KEYS
    elif group in ('l11_norms','suffix_l11_norms'):keys=backend.L11_KEYS
    else:keys=backend.WRITE_KEYS['baseline' if arm=='native_identity' else arm]
    assert set(values)==keys
    for name,value in values.items():
     gate=group in ('gate_norms','suffix_gate_norms');n=(12 if name=='source_v_norm' else 127 if group=='suffix_gate_norms' else 511) if gate else 512
     assert value.shape==(n,) and value.dtype==(np.float32 if gate and name=='s' else np.float64) and np.isfinite(value).all()
     arrays[group+'__'+arm+('__10__' if gate else '__')+name]=value
 return arrays

