 put(a.out/'export.json',{'schema':'T22_restricted_numeric_v1','canonical_run_sha256':CANONICAL['manifest.json'],'analysis_sha256':CANONICAL['l11_key_value_donor_analysis.json'],'raw_inventory_sha256':CANONICAL['numeric_inventory.json'],'audit_private_commitments':{kind:spec['sha256'] for kind,spec in AUDITS.items()},'adapter_sha256':sha(__file__),'raw_shards':32,'main_records':392,'suffix_records':384,'numeric_arrays':count,'omitted':'All input/prediction/mismatch IDs,corpus text,full gates,QKV,contexts,attention masks,hidden,vocabulary rows,timing activation samples,weights,credentials,privatehostpaths,privatefailurepayloads. Runtime fingerprints/flags remain provenance, not omitted-activation reconstruction. Typed ledger deliberately omits unselected diagnostic fields.','model_forwards':0,'second_full_model_replay':'unperformed'})
