def json_bytes(value):return (json.dumps(value,indent=2,allow_nan=False)+'\n').encode()
def pointer(value,path,replacement=None,*,write=False):
 keys=[name.replace('~1','/').replace('~0','~') for name in path.split('/')[1:]];node=value
 for name in keys[:-1]:node=node[int(name)] if isinstance(node,list) else node[name]
 name=int(keys[-1]) if isinstance(node,list) else keys[-1]
 if write:node[name]=replacement
 else:return node[name]

def public_source_bytes(run):
 result={};projections={}
 for name,h in FROZEN_SOURCE_HASHES.items():
  path=run/'frozen_sources'/name;assert sha(path)==h;data=path.read_bytes()
  if name in CERTIFICATE_LOCATOR_REPLACEMENTS:
   value=json.loads(data)
   for location,logical in CERTIFICATE_LOCATOR_REPLACEMENTS[name].items():
    base.relative_member(logical);actual=pointer(value,location)
    assert isinstance(actual,str) and actual.endswith('/pulse_transfer/'+logical)
    pointer(value,location,logical,write=True)
   rename_certificate_keys(value,name)
   data=json_bytes(value);projections[name]={'key_renames':CERTIFICATE_KEY_RENAMES.get(name,[]),'original_sha256':h,'public_sha256':hashlib.sha256(data).hexdigest(),'locator_replacements':CERTIFICATE_LOCATOR_REPLACEMENTS[name],'scope':'Only listed38host-locator values and11dictionary keys changed; all measured byte values and their order preserved. Historical numerical/source/resource/lineage claims remain original; raw local evidence is not bundled.'}
  assert hashlib.sha256(data).hexdigest()==PUBLIC_SOURCE_HASHES[name]
  assert not re.search(rb'/home/[A-Za-z0-9_.-]+/|/Users/[A-Za-z0-9_.-]+/',data),('Private host locator',name)
  result[name]=data
 assert set(projections)==set(UNSAFE_CERTIFICATES) and sum(len(v['locator_replacements']) for v in projections.values())==38
 return result,projections

def assignment_only(source,replacements):
 tree=ast.parse(source);nodes={}
 for node in tree.body:
  if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name) and node.targets[0].id in replacements:nodes[node.targets[0].id]=node
 assert set(nodes)==set(replacements)
 lines=source.splitlines(keepends=True)
 for name,node in sorted(nodes.items(),key=lambda pair:pair[1].lineno,reverse=True):lines[node.lineno-1:node.end_lineno]=[name+'='+repr(replacements[name])+'\n']
 changed=''.join(lines);restored=ast.parse(changed)
 for node in restored.body:
  if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name) and node.targets[0].id in nodes:node.value=copy.deepcopy(nodes[node.targets[0].id].value)
 assert ast.dump(restored,include_attributes=False)==ast.dump(tree,include_attributes=False),'Only declared binding assignments may change; all predicates/functions/schedule/counters/scoring stay exact'
 return changed

def staged_source_bytes(package,binding):
 """Finite consumed certificate DAG; never rewrite historical failed manifests.

 Public originals remain immutable in the package. Every derived edge is listed
 explicitly here. Original review statuses describe historical evidence; these
 metadata derivatives are not new model/audit executions. A separate reviewed
 portable-binding receipt is mandatory before staging can be activated.
 """
 assert STAGE_BINDING_REVIEW_SHA is not None,'HOLD: independent review of the portable DAG and its changed-ABI fixtures is not yet pinned'
 source=package/'experiments/pulse_transfer';original={n:(source/n).read_bytes() for n in FROZEN_SOURCE_HASHES}
 assert all(hashlib.sha256(v).hexdigest()==PUBLIC_SOURCE_HASHES[n] for n,v in original.items())
 assert binding['original']==CANONICAL_INPUTS and set(binding['regenerated'])==set(CANONICAL_INPUTS)
 assert binding['regenerated']['tokens.pt']==CANONICAL_INPUTS['tokens.pt'] and binding['regenerated']['known_history_chain.json']==CANONICAL_INPUTS['known_history_chain.json']
 derived={};visiting=set();changes={}
 def visit(name):
  if name in derived:return derived[name]
  assert name not in visiting,'Certificate DAG cycle';visiting.add(name);data=original[name]
  edges=CERTIFICATE_HASH_EDGES.get(name,{})
  if edges or name=='review/t22_actual_input_independent_audit.json':
   value=json.loads(data);before=copy.deepcopy(value);record=[]
   for location,target in edges.items():
    old=pointer(value,location);assert old==FROZEN_SOURCE_HASHES[target]
    new=hashlib.sha256(visit(target)).hexdigest();pointer(value,location,new,write=True);record.append({'pointer':location,'target':target,'original_sha256':old,'staged_sha256':new})
   if name=='review/t22_actual_input_independent_audit.json':
    assert value['actual_preparation_sha256']==CANONICAL_INPUTS and value['audited_data_manifest_sha256']==CANONICAL_INPUTS['data_manifest.json']
    value['actual_preparation_sha256']=binding['regenerated'];value['audited_data_manifest_sha256']=binding['regenerated']['data_manifest.json']
    record.append({'pointer':'/actual_preparation_sha256','original':CANONICAL_INPUTS,'staged':binding['regenerated']});record.append({'pointer':'/audited_data_manifest_sha256','original_sha256':CANONICAL_INPUTS['data_manifest.json'],'staged_sha256':binding['regenerated']['data_manifest.json']})
   if value!=before:data=json_bytes(value);changes[name]=record
  visiting.remove(name);derived[name]=data;return data
 for name in FROZEN_SOURCE_HASHES:visit(name)
 runner='gpt2_l11_key_value_donor.py';text=original[runner].decode()
 pins=copy.deepcopy(base.assigned(text,'REVIEWED_FILE_PINS')[1]);final=copy.deepcopy(base.assigned(text,'FINAL_CERTIFICATE_PINS')[1])
 for name in pins:assert pins[name]==FROZEN_SOURCE_HASHES[name];pins[name]=hashlib.sha256(derived[name]).hexdigest()
 for value in final.values():assert value['sha256']==FROZEN_SOURCE_HASHES[value['path']];value['sha256']=hashlib.sha256(derived[value['path']]).hexdigest()
 derived[runner]=assignment_only(text,{'INPUT_HASHES':binding['regenerated'],'AUDITED_INPUT_HASHES':binding['regenerated'],'REVIEWED_FILE_PINS':pins,'FINAL_CERTIFICATE_PINS':final}).encode()
 # A replay source closure differs honestly; historical original claims stay in
 # separate namespaces, never relabelled as the new staged execution.
 receipt={'schema':'T22_portable_certificate_binding_v1','status':'prepared_not_executed','policy_review_sha256':PORTABLE_POLICY_REVIEW_SHA,'stage_binding_review_sha256':STAGE_BINDING_REVIEW_SHA,'canonical_original_sha256':FROZEN_SOURCE_HASHES,'public_view_sha256':PUBLIC_SOURCE_HASHES,'staged_sha256':{n:hashlib.sha256(v).hexdigest() for n,v in derived.items()},'certificate_edges':changes,'runner_assignments':['INPUT_HASHES','AUDITED_INPUT_HASHES','REVIEWED_FILE_PINS','FINAL_CERTIFICATE_PINS'],'guard_predicates_functions_order_and_scoring_AST_exact':True,'historical_failed_manifests_byte_exact':all(derived[n]==original[n] for n in ('gpt2_l11_key_value_donor_run_A/manifest.json','gpt2_l11_key_value_donor_run_A_r2/manifest.json')),'scope':'Certificate/source guards are preserved, with metadata-only reviewed portable bindings. Original reports/audits describe the original execution, not a new historical audit of regenerated bytes. Full new776 model replay and its independent comparators remain unperformed.','model_forwards':0}
 assert receipt['historical_failed_manifests_byte_exact'];safe(receipt);return derived,receipt

def assert_public_audit(value,kind):
 schema=copy.deepcopy(RAW_AUDIT_SHAPES[kind])
 if kind=='numerical':schema={name:schema[name] for name in N_PUBLIC_ROOTS}
 elif kind=='readout':
  for state in schema['states'].values():
   del state['prediction']
   for row in state['argmax_mismatches'][1:]:del row['left_id'];del row['right_id']
 schema['private_report_sha256']='str';schema['public_omissions']='str'
 assert_typed(value,schema);safe(value)
 spec=AUDITS[kind];assert value['private_report_sha256']==spec['sha256'] and value['auditor_sha256']==spec['auditor_sha256'] and value['schema']==spec['schema'] and value['status']=='passed' and value['run_manifest_sha256']==CANONICAL['manifest.json']
 if kind=='numerical':assert value['analysis_sha256']==CANONICAL['l11_key_value_donor_analysis.json'] and value['raw_inventory_sha256']==CANONICAL['numeric_inventory.json']
 else:assert value['inventory_sha256']==CANONICAL['numeric_inventory.json']
 if kind=='readout':
  assert value['query_rows']==[1,126,127,510] and value['target_positions']==[2,127,128,511]
  for state in value['states'].values():
   rows=state['small_KL_saved_gpu_logit_diagnostics'];assert [row['query'] for row in rows]==[1,126,127,510]
   for row in rows:assert row['reference_is_exact_zero']==(row['absolute_reference_kl']==0) and ((row['absolute_error_to_signal'] is None)==row['reference_is_exact_zero'])
   for row in state['argmax_mismatches']:assert row['query'] in (1,126,127,510)
 return value

