 anchor=metadata['window']==0 and metadata['identity']=='natural';main=set(ARMS)|({'native_repeat','native_identity'} if anchor else set());suffix=set(ARMS)
 assert set(ledger['operations'])==set(ledger['final_hidden_fingerprints'])==main and set(ledger['suffix_operations'])==set(ledger['suffix_final_hidden_fingerprints'])==suffix
